INSERT INTO `news_item` VALUES (5,_binary '','校园',_binary '','2026-10-19 22:02:32.537966','校园网','第十三届校园科技节在体育馆开幕，高一同学带来的水火箭、循迹机器人项目吸引了不少围观。','校园科技节开幕，水火箭与机器人同台亮相',NULL,NULL,NULL),(6,_binary '','校园',_binary '\0','2026-10-19 01:02:32.537966','德育处','同学们分组完成“城市记忆”主题探究任务，在实景中理解历史课本里的城市变迁。','高一年级开展秋季研学：走进城市博物馆',NULL,NULL,NULL),(7,_binary '','科技',_binary '\0','2026-10-18 01:02:32.537966','中国载人航天','航天员在轨演示微重力下的流体与燃烧实验，学校组织各班在班会课集中观看。','“天宫课堂”新一期开讲，太空实验再次点燃好奇心',NULL,NULL,NULL),(8,_binary '','文化',_binary '\0','2026-10-17 01:02:32.537966','图书馆','语文组整理出 20 本适合高中生阅读的书籍，图书馆同步设置专题展架。','校园读书月推荐书单发布',NULL,NULL,NULL),(132,_binary '','教育',_binary '\0','2026-10-27 00:00:00.000000','新华网','来自新华网的最新教育资讯，点击「查看原文」阅读全文。','中央机关及其直属机构2027年度考试录用公务员网上报名与资格审查工作结束','http://education.news.cn/20261027/04f9d3a99164410ca90cdb00349abd2a/c.html','xinhua-edu:f865f9232b1d0f8f',''),(133,_binary '','教育',_binary '\0','2026-10-27 00:00:00.000000','中国教育新闻网','来自中国教育新闻网的最新教育资讯，点击「查看原文」阅读全文。','新华社社评：以永远在路上的坚韧和执着推进全面从严治党','http://www.jyb.cn/rmtzcg/xwy/wzxw/202610/t20261027_2111535433.html','jyb:a291bce014abc1cb',''),(134,_binary '','教育',_binary '\0','2026-10-27 00:00:00.000000','中国教育新闻网','来自中国教育新闻网的最新教育资讯，点击「查看原文」阅读全文。','坚持党的全面领导，不断提高党的长期执政能力','http://www.jyb.cn/rmtzgjyb/202610/t20261027_2111535025.html','jyb:790e5b23ce0cb85e',''),(135,_binary '','教育',_binary '\0','2026-10-27 00:00:00.000000','中国教育新闻网','来自中国教育新闻网的最新教育资讯，点击「查看原文」阅读全文。','中央第十巡视组巡视教育部党组工作动员会召开','http://www.jyb.cn/rmtzgjyb/202610/t20261027_2111535027.html','jyb:ed30bdf0324395e8',''),(136,_binary '','教育',_binary '\0','2026-10-27 00:00:00.000000','中国教育新闻网','来自中国教育新闻网的最新教育资讯，点击「查看原文」阅读全文。','深化教学关键要素改革 夯实现代职教体系根基','http://www.jyb.cn/rmtzgjyb/202610/t20261027_2111535048.html','jyb:e37a7b53c5957a3f',''),(137,_binary '','教育',_binary '\0','2026-10-27 00:00:00.000000','中国教育新闻网','来自中国教育新闻网的最新教育资讯，点击「查看原文」阅读全文。','产业往哪里走，专业就往哪里跟','http://www.jyb.cn/rmtzgjyb/202610/t20261027_2111535037.html','jyb:1a6f73542f5e2c21',''),(138,_binary '','教育',_binary '\0',